package main

// The overview stays short; command pages retain the argument and policy facts.
var commandDetails = map[string]struct{ description, examples string }{
	"status":      {"Show the daemon's state, counts, uptime and your authenticated identity. No positional arguments.", "agent-bus status"},
	"ls":          {"With no name or filter, show agents being read now. <name> shows one record; --kind lists every visible record of that kind, and --all lists all visible kinds. Output is JSON unless -h or --table requests a readable table.", "agent-bus ls -h\nagent-bus ls '#worker@demo'"},
	"send":        {"<to> is the destination; <text> is the message, or - reads stdin. Send once without waiting for an answer. An ask flag takes <to> with no text. --reply-to chooses the inbox for later answers. Use -- before literal text beginning with --.", "agent-bus send '#worker@demo' 'build main'\nagent-bus send '#worker@demo' --status"},
	"call":        {"<to> is the destination; <text> is the message, or - reads stdin. Send once and wait for answer. With --tagged, <body> is one quoted argument sent to all visible agents with that tag. An ask flag takes <to> with no text; call <to> --help asks the agent, while help call describes this command. An uncertain result must not be retried blindly.", "agent-bus call '#worker@demo' --wait=30s 'build main'\nagent-bus call --tagged=systemd failed"},
	"consume":     {"Take a message from your own inbox, or --inbox. --topic and --tag filter what is taken. --share makes this process one of several workers behind the same name. --follow keeps reading after each long poll. No positional arguments.", "agent-bus consume --wait=30s\nagent-bus consume --inbox=jobs@demo --share --follow"},
	"reply":       {"<message-id> identifies a message this CLI previously consumed; its saved reply destination, topic and tag are used. <text> is the answer. With --to, give the reply destination and original topic/tag directly instead of a message id.", "agent-bus reply \"$message_id\" 'finished'\nagent-bus reply --to='#caller@demo' --topic=build --tag=job42 'finished'"},
	"run":         {"<name> is the agent to register; <script> is one quoted shell command. The default input form is args. A lone - reads the agent declaration as JSON from stdin; -N overrides its parallel worker count (default 1). Confinement is off unless --sandbox=on; a confined script has no network unless --network is given. --package-dir answers packaged help before launching a script. Understood roles arrive per message as AB_ROLE_<NAME>=1. Keep secrets in Secret and settings in Configuration; scripts receive compact AGENT_BUS_CONFIG at their next start, unset when unconfigured. --no-asks answers unsupported asks without launching the script; --stay-registered keeps the record and credential after a graceful stop.", "agent-bus run hello './hello.sh'\nagent-bus run -4 - < agent.json"},
	"ack":         {"<message-id> identifies a consumed message. Send a receipt saying it was received; this is not an answer.", "agent-bus ack \"$message_id\""},
	"done":        {"<message-id> identifies a consumed task that expects no answer. Send a completion receipt; do not send done after an answer.", "agent-bus done \"$message_id\""},
	"publish":     {"--channel names the destination channel; <text> is the publication. A pubsub channel copies it to its delivery list. A queue keeps one copy for its readers.", "agent-bus publish --channel=alerts@demo 'build finished'"},
	"unsubscribe": {"<channel> is a pubsub channel. Remove your inbox from its delivery list so you stop receiving copies. The channel's owner manages that list on its settings page.", "agent-bus unsubscribe alerts@demo"},
	"register":    {"<name> names the new record. A # name registers an agent; without a kind, an ordinary name registers an external service, which needs --service-addr and --protocol. --personal implies agent; --uri describes a resource card. --allow says who may see and use it. TTL is retention and bound is queue capacity. Pubsub copies use each recipient's retention, not their own queue settings.", "agent-bus register '#worker@demo' --allow='@owner'\nagent-bus register jobs@demo --kind=queue --ttl=1h --bound=1000"},
	"unregister":  {"<name> names an idle record to remove. This removes the registry entry; it does not stop a process. A running agent may register itself again.", "agent-bus unregister '#worker@demo'"},
	"manage":      {"<name> names the record to change. --deliver-to sets an agent's or queue's one route; an empty value clears it. --roles replaces understood roles; an empty value clears them. --tags replaces all tags. For allow, maintainers, deliver-to and tags: --add appends, --add-to-set adds without duplicates, and --remove removes the listed terms. Comma-separated values may include users, groups or access terms as appropriate.", "agent-bus manage '#worker@demo' --add-to-set-allow=bob@demo\nagent-bus manage '#worker@demo' --deliver-to=''"},
	"may-send":    {"<name> is the proposed destination. Check the same target permission as send, but queue nothing. This does not promise queue capacity or onward delivery.", "agent-bus may-send '#worker@demo'"},
	"stop":        {"<name> identifies a script agent started on this host. Ask it to stop gracefully and wait for it to finish. Other agents are untouched.", "agent-bus stop '#hello'"},
	"logs":        {"<name> identifies a script agent started on this host. Show its recent output, which remains after the process stops. --follow prints new output as it arrives.", "agent-bus logs '#hello' --lines=50\nagent-bus logs '#hello' --follow"},
	"config":      {"<name> names the record. With no value, read its JSON Configuration; <json> sets it inline, and - reads stdin. The record's Owner, Maintainers and own Agent may read it; other callers cannot. The web shows Configuration only to managers. Scripts receive compact AGENT_BUS_CONFIG at their next start, unset when unconfigured. Put credentials in Secret, never Configuration.", "agent-bus config '#worker@demo'\nagent-bus config '#worker@demo' '{\"mode\":\"safe\"}'"},
	"secret":      {"<name> names the record. With no value, print its private Secret; <bytes> sets it inline, and - reads stdin. Only its Owner, Maintainers and own Agent may read it. The web never displays stored Secret values. Prefer stdin when setting a secret to keep its value out of shell arguments and history.", "agent-bus secret '#worker@demo' - < private.env"},
	"group":       {"<@name> names a group. With no members, print its current membership; with <member> arguments, replace it with those users or groups.", "agent-bus group @builders@demo\nagent-bus group @builders@demo alice@demo bob@demo"},
	"kv": {"<record> names the store; <key> names a value. Its Owner, Maintainers and own Agent may use it. get reads; set writes <value> (or stdin with -); delete removes. inc adds [n], default 1, to an integer and prints it. json applies a JSON array of key operations atomically: all or none. Storage is string by default; --int and --json select separate types. --add writes only if absent, --replace only if present (set only).",
		"agent-bus kv set '#worker@demo' jobs '{\"pending\":[]}' --json --add\nagent-bus kv json '#worker@demo' jobs '[{\"op\":\"push\",\"key\":\"pending\",\"value\":1}]'"},
	"lock":     {"<record> is the lock namespace; <name> is the lock to take. The record's Owner, Maintainers and own Agent may take its locks. Wait up to --wait, then grant or refuse. A granted lock expires after --ttl unless extended.", "agent-bus lock '#worker@demo' deploy --ttl=30s --wait=30s"},
	"try-lock": {"<record> is the lock namespace; <name> is the lock to take. The record's Owner, Maintainers and own Agent may take its locks. Grant or refuse immediately without waiting; a granted lock expires after --ttl.", "agent-bus try-lock '#worker@demo' deploy --ttl=30s"},
	"release":  {"<record> is the lock namespace; <name> is the lock to release. Release your own lock, or use --force as a manager to release another holder's lock.", "agent-bus release '#worker@demo' deploy"},
	"extend":   {"<record> is the lock namespace; <name> is your held lock. Set a fresh lease lifetime with --ttl; this does not transfer the lock.", "agent-bus extend '#worker@demo' deploy --ttl=30s"},
	"holders":  {"<record> names the lock namespace. Print each held lock, its holder and remaining lifetime, or say no locks are held.", "agent-bus holders '#worker@demo'"},
	"token":    {"<name> is an optional bus principal: a user or #agent, with optional realm. With no name, use the authenticated login socket's identity. Get the existing credential unless --rotate is requested. --fingerprint prints the daemon's public TLS pin instead. An SSH forced command may request only its entitled principal.", "agent-bus token > private.token\nagent-bus token --fingerprint"},
	"enrol":    {"<user[@realm]> names the identity to prove. Sign the daemon's challenge with a key published by that realm; naming a key alone does not prove possession.", "agent-bus enrol alice@github --key=\"$HOME/.ssh/id_ed25519\""},
}
